function smallestUniqueSubarray(nums) {
  const n = nums.length;
  const levels = [nums];
  for (let len = 2; len <= n; len *= 2) {
    const half = len / 2;
    const prev = levels[levels.length - 1];
    const ids = [];
    const map = new Map();
    for (let i = 0; i + len <= n; i++) {
      const left = prev[i];
      const right = prev[i + half];
      const key = `${left},${right}`;
      if (!map.has(key)) {
        map.set(key, map.size);
      }
      ids.push(map.get(key));
    }
    levels.push(ids);
  }
  function hasUnique(k) {
    const level = Math.floor(Math.log2(k));
    const len = 2 ** level;
    const ids = levels[level];
    const counts = new Map();
    for (let i = 0; i + k <= n; i++) {
      const left = ids[i];
      const right = ids[i + k - len];
      const key = `${left},${right}`;
      counts.set(key, (counts.get(key) || 0) + 1);
    }
    for (const count of counts.values()) {
      if (count === 1) return true;
    }
    return false;
  }
  let lo = 1;
  let hi = n;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (hasUnique(mid)) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return lo;
}

var smallestUniqueSubarray = function(nums) {
    const n = nums.length;
    let largest = 0;

    for (const num of nums) {
        largest = Math.max(largest, num);
    }

    const BASE = largest + 1;
    const MOD = 1000000007;

    function hasUnique(k) {
        // The first value in a k-element window has weight BASE^(k - 1).
        let power = 1;
        for (let i = 1; i < k; i++) {
            power = (power * BASE) % MOD;
        }

        const buckets = new Map();
        let hash = 0;

        // a and b are window starts; j is the offset within each window.
        function sameWindow(a, b) {
            for (let j = 0; j < k; j++) {
                if (nums[a + j] !== nums[b + j]) {
                    return false;
                }
            }
            return true;
        }

        function recordWindow(start) {
            let groups = buckets.get(hash);

            if (!groups) {
                groups = [];
                buckets.set(hash, groups);
            }

            // Equal hashes can represent different subarrays.
            // Increase a count only after comparing the actual elements.
            for (const group of groups) {
                if (sameWindow(group.start, start)) {
                    group.count++;
                    return;
                }
            }

            groups.push({ start: start, count: 1 });
        }

        // Build the first window's hash from left to right.
        for (let i = 0; i < k; i++) {
            hash = (hash * BASE + nums[i]) % MOD;
        }
        recordWindow(0);

        // Remove the outgoing value, shift the weights, and add the new value.
        for (let start = 1; start + k <= n; start++) {
            const out = (nums[start - 1] * power) % MOD;
            hash = (hash - out + MOD) % MOD;
            hash = (hash * BASE + nums[start + k - 1]) % MOD;
            recordWindow(start);
        }

        for (const groups of buckets.values()) {
            for (const group of groups) {
                if (group.count === 1) return true;
            }
        }
        return false;
    }

    let lo = 1;
    let hi = n;
    let ans = n;

    while (lo <= hi) {
        const mid = Math.floor((lo + hi) / 2);

        if (hasUnique(mid)) {
            ans = mid;
            hi = mid - 1;
        } else {
            lo = mid + 1;
        }
    }

    return ans;
};

var smallestUniqueSubarray = function(nums) {
    // STEP 1: Generate every suffix.
    const suffixes = nums.map((_, i) => nums.slice(i));

    // STEP 2: Sort suffixes lexicographically.
    suffixes.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++) {
            if (a[i] !== b[i]) {
                return a[i] - b[i];
            }
        }

        return a.length - b.length;
    });

    // STEP 3: Find the longest matching prefix
    // between two suffixes.
    function lcp(a, b) {
        if (!a || !b) return 0;

        let i = 0;

        while (
            i < a.length &&
            i < b.length &&
            a[i] === b[i]
        ) {
            i++;
        }

        return i;
    }

    // STEP 4: Find the shortest unique prefix
    // for every suffix.
    let best = nums.length;

    for (let i = 0; i < suffixes.length; i++) {
        const curr = suffixes[i];

        const prevLcp = lcp(curr, suffixes[i - 1]);
        const nextLcp = lcp(curr, suffixes[i + 1]);

        const needed = Math.max(prevLcp, nextLcp) + 1;

        // The suffix must contain enough elements.
        if (needed <= curr.length) {
            best = Math.min(best, needed);
        }
    }

    return best;
};

var smallestUniqueSubarraySuffixArray = function(nums) {
    const n = nums.length;
    if (n === 1) return 1;

    // STEP 1: Give equal numbers equal ranks.
    const sorted = [...nums].sort((a, b) => a - b);
    const ranks = Object.create(null);
    let groups = 0;

    for (const num of sorted) {
        if (ranks[num] === undefined) {
            ranks[num] = groups;
            groups++;
        }
    }

    let rank = nums.map(num => ranks[num]);
    let sa = Array.from({ length: n }, (_, i) => i);

    // Stable counting sort for one half of a rank pair.
    // A missing second half has rank -1, ordered before other ranks.
    function countSort(ids, offset) {
        const count = new Int32Array(groups + 1);

        for (const start of ids) {
            const key = start + offset < n ? rank[start + offset] + 1 : 0;
            count[key]++;
        }

        let p = 0;
        for (let key = 0; key < count.length; key++) {
            const size = count[key];
            count[key] = p;
            p += size;
        }

        const out = new Array(n);
        for (const start of ids) {
            const key = start + offset < n ? rank[start + offset] + 1 : 0;
            out[count[key]++] = start;
        }
        return out;
    }

    // STEP 2: Sort suffixes by doubling the compared prefix length.
    // First sort by the second half, then the first half.
    for (let gap = 1; gap < n; gap *= 2) {
        sa = countSort(sa, gap);
        sa = countSort(sa, 0);

        const nextRank = new Array(n);
        nextRank[sa[0]] = 0;
        let classes = 1;

        for (let i = 1; i < n; i++) {
            const prev = sa[i - 1];
            const curr = sa[i];
            const prev2 = prev + gap < n ? rank[prev + gap] : -1;
            const curr2 = curr + gap < n ? rank[curr + gap] : -1;

            const diff = rank[prev] !== rank[curr] || prev2 !== curr2;
            if (diff) classes++;
            nextRank[curr] = classes - 1;
        }

        rank = nextRank;
        groups = classes;
        if (groups === n) break;
    }

    // STEP 3: Calculate LCP between neighboring sorted suffixes.
    // lcp[i] is the common prefix length of sa[i-1] and sa[i].
    const pos = new Array(n);
    for (let i = 0; i < n; i++) {
        pos[sa[i]] = i;
    }

    const lcp = new Array(n).fill(0);
    let common = 0;

    for (let start = 0; start < n; start++) {
        const i = pos[start];
        if (i === 0) {
            common = 0;
            continue;
        }

        const prev = sa[i - 1];
        while (start + common < n && prev + common < n && nums[start + common] === nums[prev + common]) {
            common++;
        }

        lcp[i] = common;
        if (common > 0) common--;
    }

    // STEP 4: The first unique prefix has length max(neighbor LCPs) + 1.
    let best = n;

    for (let i = 0; i < n; i++) {
        const prevLcp = lcp[i];
        const nextLcp = lcp[i + 1] ?? 0;
        const needed = Math.max(prevLcp, nextLcp) + 1;
        const len = n - sa[i];

        if (needed <= len) {
            best = Math.min(best, needed);
        }
    }

    return best;
};

var smallestUniqueSubarray = function(nums) {
    const ROOT = 0;
    const NONE = -1;
    // len: longest length; link: shorter suffix state; count: occurrences.
    const nodes = [
        { len: 0, link: NONE, next: {}, count: 0 }
    ];
    let last = ROOT;

    // Copy an existing node's transitions into a clone, but split off only
    // the shorter paths. A clone is NOT a new input position (count = 0).
    // p is a shorter suffix state; q is its existing transition on value x.
    function splitNode(p, q, x) {
        const clone = nodes.length;

        nodes.push({
            len: nodes[p].len + 1,
            link: nodes[q].link,
            next: { ...nodes[q].next },
            count: 0
        });

        // Redirect all shorter-path transitions that still point at q.
        while (
            p !== NONE &&
            nodes[p].next[x] === q
        ) {
            nodes[p].next[x] = clone;
            p = nodes[p].link;
        }

        nodes[q].link = clone;
        return clone;
    }

    // Build the suffix automaton one input number at a time.
    for (const x of nums) {
        const curr = nodes.length;

        nodes.push({
            len: nodes[last].len + 1,
            link: NONE,
            next: {},
            count: 1
        });

        // If no existing transition is found, root is the default.
        nodes[curr].link = ROOT;
        let p = last;

        while (p !== NONE) {
            const q = nodes[p].next[x];
            const exists = q !== undefined;

            if (exists) {
                const expected = nodes[p].len + 1;
                const actual = nodes[q].len;
                const split = expected !== actual;

                nodes[curr].link = split
                    ? splitNode(p, q, x)
                    : q;

                break;
            }

            nodes[p].next[x] = curr;
            p = nodes[p].link;
        }

        last = curr;
    }

    // Turn suffix links into a parent -> children tree.
    const kids = Array.from({ length: nodes.length }, () => []);
    for (let id = 1; id < nodes.length; id++) {
        const parent = nodes[id].link;
        kids[parent].push(id);
    }

    // Visit parents first, then reverse this order when propagating counts.
    const stack = [ROOT];
    const order = [];

    while (stack.length > 0) {
        const id = stack.pop();
        order.push(id);

        for (const child of kids[id]) {
            stack.push(child);
        }
    }

    // Propagate each node's occurrence count to its shorter-node parent.
    for (let i = order.length - 1; i > 0; i--) {
        const child = order[i];
        const parent = nodes[child].link;
        nodes[parent].count += nodes[child].count;
    }

    // Find the shortest length represented by a node occurring exactly once.
    let best = nums.length;

    for (let id = 1; id < nodes.length; id++) {
        const unique = nodes[id].count === 1;
        if (!unique) continue;

        const p = nodes[id].link;
        const len = nodes[p].len + 1;
        best = Math.min(best, len);
    }

    return best;
};
